export function assignCrowdPaths(people){
  const byKey=new Map(paths.map(p=>[p.key,p.points]));
  for(const p of people.people){
    if(!p.route||!p.walk)continue;
    const points=byKey.get(JSON.stringify([p.kind,...p.route]));if(!points)continue;
    let length=0;const segments=[];
    for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],size=Math.hypot(b[0]-a[0],b[1]-a[1]);if(size<1e-7)continue;segments.push({a,b,start:length,length:size});length+=size;}
    if(length>0)p.crowdPath={points,segments,length};
  }
}
